                                                                                                                                                                    // 1. Android Share-Target Parameter auslesen & Check24-Prosa bereinigen
                                                                                                                                                                    function parseSharedData() {
                                                                                                                                                                      const params = new URLSearchParams(window.location.search);
                                                                                                                                                                        const rawTitle = params.get('title') || '';
                                                                                                                                                                          const rawText = params.get('text') || '';
                                                                                                                                                                            const rawUrl = params.get('url') || '';

                                                                                                                                                                              if (!rawTitle && !rawText && !rawUrl) return;

                                                                                                                                                                                const combined = `${rawTitle}\n${rawText}\n${rawUrl}`.trim();
                                                                                                                                                                                  const urlMatch = combined.match(/https?:\/\/[^\s]+/i);

                                                                                                                                                                                    const urlInput = document.getElementById('url');
                                                                                                                                                                                      const nameInput = document.getElementById('hotelName');

                                                                                                                                                                                        if (urlMatch && urlInput) {
                                                                                                                                                                                            urlInput.value = urlMatch[0];
                                                                                                                                                                                              }

                                                                                                                                                                                                // Wenn title sauber gesetzt ist, direkt bevorzugen – sonst aus text extrahieren
                                                                                                                                                                                                  let candidate = rawTitle.replace(/https?:\/\/[^\s]+/gi, '').trim();
                                                                                                                                                                                                    if (!candidate || /check24/i.test(candidate)) {
                                                                                                                                                                                                        candidate = `${rawTitle} ${rawText}`
                                                                                                                                                                                                              .replace(/https?:\/\/[^\s]+/gi, ' ')
                                                                                                                                                                                                                    .replace(/Folgendes Hotel habe ich bei\s*(CHECK24)?\s*gefunden:?/gi, ' ')
                                                                                                                                                                                                                          .replace(/Viel Spaß beim Buchen deines Traumurlaubs\.?/gi, ' ')
                                                                                                                                                                                                                                .replace(/Schau dir dieses Hotel.*?an:?/gi, ' ')
                                                                                                                                                                                                                                      .replace(/CHECK24/gi, ' ')
                                                                                                                                                                                                                                            .replace(/\s+/g, ' ')
                                                                                                                                                                                                                                                  .trim();
                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                      // Doppelten Namen entfernen ("The Grand Resort The Grand Resort" -> "The Grand Resort")
                                                                                                                                                                                                                                                        const words = candidate.split(' ');
                                                                                                                                                                                                                                                          if (words.length >= 2 && words.length % 2 === 0) {
                                                                                                                                                                                                                                                              const mid = words.length / 2;
                                                                                                                                                                                                                                                                  const first = words.slice(0, mid).join(' ');
                                                                                                                                                                                                                                                                      const second = words.slice(mid).join(' ');
                                                                                                                                                                                                                                                                          if (first.toLowerCase() === second.toLowerCase()) {
                                                                                                                                                                                                                                                                                candidate = first;
                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                        if (candidate && nameInput && !nameInput.value) {
                                                                                                                                                                                                                                                                                            nameInput.value = candidate;
                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                              async function fetchJsonSafe(url, options = {}, timeoutMs = 6000) {
                                                                                                                                                                                                                                                                                                const controller = new AbortController();
                                                                                                                                                                                                                                                                                                  const timer = setTimeout(() => controller.abort(), timeoutMs);
                                                                                                                                                                                                                                                                                                    try {
                                                                                                                                                                                                                                                                                                        const res = await fetch(url, { ...options, signal: controller.signal });
                                                                                                                                                                                                                                                                                                            const text = await res.text();
                                                                                                                                                                                                                                                                                                                if (!res.ok) throw new Error(`HTTP ${res.status}`);
                                                                                                                                                                                                                                                                                                                    return JSON.parse(text);
                                                                                                                                                                                                                                                                                                                      } finally {
                                                                                                                                                                                                                                                                                                                          clearTimeout(timer);
                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                            // 2. Geocoding über Nominatim
                                                                                                                                                                                                                                                                                                                            async function geocodeHotel(hotelName, location) {
                                                                                                                                                                                                                                                                                                                              const headers = { 'Accept-Language': 'de' };
                                                                                                                                                                                                                                                                                                                                const queries = [`${hotelName}, ${location}`, location];

                                                                                                                                                                                                                                                                                                                                  for (const q of queries) {
                                                                                                                                                                                                                                                                                                                                      try {
                                                                                                                                                                                                                                                                                                                                            const data = await fetchJsonSafe(
                                                                                                                                                                                                                                                                                                                                                    `https://nominatim.openstreetmap.org/search?format=json&limit=1&q=${encodeURIComponent(q)}`,
                                                                                                                                                                                                                                                                                                                                                            { headers },
                                                                                                                                                                                                                                                                                                                                                                    6000
                                                                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                                                                                if (data && data.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                        return {
                                                                                                                                                                                                                                                                                                                                                                                                  lat: parseFloat(data[0].lat),
                                                                                                                                                                                                                                                                                                                                                                                                            lon: parseFloat(data[0].lon),
                                                                                                                                                                                                                                                                                                                                                                                                                      exact: q.includes(hotelName)
                                                                                                                                                                                                                                                                                                                                                                                                                              };
                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                        } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                              console.warn('Nominatim Versuch fehlgeschlagen:', q, err);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                      throw new Error('Ort konnte auf OpenStreetMap nicht gefunden werden.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                      function haversineMeters(lat1, lon1, lat2, lon2) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                        const R = 6371000;
                                                                                                                                                                                                                                                                                                                                                                                                                                                          const toRad = (deg) => (deg * Math.PI) / 180;
                                                                                                                                                                                                                                                                                                                                                                                                                                                            const dLat = toRad(lat2 - lat1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                              const dLon = toRad(lon2 - lon1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                const a =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    Math.sin(dLat / 2) ** 2 +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return Math.round(R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a)));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                          // 3a. Nächsten Flughafen aus der lokalen Datenbank bestimmen (0 ms!)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function findNearestAirport(lat, lon) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let nearest = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              let minDist = Infinity;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                for (const ap of AIRPORTS) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const d = haversineMeters(lat, lon, ap.lat, ap.lon);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (d < minDist) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              minDist = d;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    nearest = { ...ap, airMeters: d };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return minDist <= 250000 ? nearest : null; // max. 250 km Umkreis
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 3b. Strand-Distanz blitzschnell über Nominatim Bounded Search
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            async function findNearestBeachMeters(lat, lon) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // Bounding Box ca. +/- 0.04 Grad (~4 km Umkreis)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const d = 0.04;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const viewbox = `${lon - d},${lat + d},${lon + d},${lat - d}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const url = `https://nominatim.openstreetmap.org/search?format=json&limit=5&bounded=1&viewbox=${viewbox}&q=beach`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const data = await fetchJsonSafe(url, { headers: { 'Accept-Language': 'de' } }, 5000);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (data && data.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            let minMeters = Infinity;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for (const item of data) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const m = haversineMeters(lat, lon, parseFloat(item.lat), parseFloat(item.lon));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (m < minMeters) minMeters = m;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return minMeters;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        console.warn('Strand-Abfrage fehlgeschlagen:', err);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // 4. OSRM: Echte Auto-Fahrtdauer zum Flughafen
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            async function fetchDriveMinutes(fromLat, fromLon, toLat, toLon) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const url = `https://router.project-osrm.org/route/v1/driving/${fromLon},${fromLat};${toLon},${toLat}?overview=false`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const data = await fetchJsonSafe(url, {}, 6000);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (data.routes && data.routes.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return Math.round(data.routes[0].duration / 60);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          console.warn('OSRM Routing fehlgeschlagen:', err);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // Speicher-Helfer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              function getHotels() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return JSON.parse(localStorage.getItem(STORAGE_KEY) || '[]');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function saveHotels(list) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    renderList();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function deleteHotel(index) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const list = getHotels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        list.splice(index, 1);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          saveHotels(list);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          function renderList() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const list = getHotels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              document.getElementById('countBadge').textContent = list.length;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const container = document.getElementById('hotelList');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (list.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      container.innerHTML = '<p style="color:#94a3b8;font-size:0.85rem;">Noch keine Hotels gespeichert.</p>';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              container.innerHTML = list
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .map(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (h, i) => `
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              <div class="item">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      <div class="item-head">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                <span>${h.hotelName} (${h.price ? h.price + ' €' : 'k. A.'})</span>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <button class="btn-del" onclick="deleteHotel(${i})">✕</button>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          <div class="meta">
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    📍 ${h.location} · ✈️ ${h.airportIata || '?'} (${h.airportMinutes !== '' ? h.airportMinutes + ' Min.' : '?'}) · 🏖️ ${h.beachMeters !== null && h.beachMeters !== '' ? h.beachMeters + ' m' : '> 4 km'}
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            </div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    <div class="meta">${h.board} · ${'⭐'.repeat(Number(h.rating))} ${h.notes ? '· ' + h.notes : ''}</div>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          </div>`
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  .join('');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  // 5. Formular-Submit
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  document.getElementById('hotelForm').addEventListener('submit', async (e) => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    e.preventDefault();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const btn = document.getElementById('saveBtn');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const status = document.getElementById('status');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          btn.disabled = true;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const hotelName = document.getElementById('hotelName').value.trim();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const location = document.getElementById('location').value.trim();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    status.textContent = '1/3 Suche Hotel-Koordinaten...';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const coords = await geocodeHotel(hotelName, location);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            status.textContent = '2/3 Suche Strand & nächsten Flughafen...';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const airport = findNearestAirport(coords.lat, coords.lon);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const beachMeters = await findNearestBeachMeters(coords.lat, coords.lon);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        let airportMinutes = null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (airport) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  status.textContent = `3/3 Berechne Fahrtdauer nach ${airport.iata}...`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        airportMinutes = await fetchDriveMinutes(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                coords.lat,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        coords.lon,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                airport.lat,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        airport.lon
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // Fallback falls OSRM für eine Insel-Route mal keine Straße findet: Schätzung aus Luftlinie (~65 km/h)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (airportMinutes === null) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  airportMinutes = Math.max(5, Math.round((airport.airMeters / 1000) * 1.1));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const entry = {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      datum: new Date().toLocaleDateString('de-DE'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            hotelName,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  location,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        price: document.getElementById('price').value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              board: document.getElementById('board').value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    rating: document.getElementById('rating').value,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          travelDate: document.getElementById('travelDate').value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                airportIata: airport ? `${airport.name} (${airport.iata})` : 'Nicht in Liste',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      airportMinutes: airportMinutes ?? '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            beachMeters: beachMeters ?? '',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  exactMatch: coords.exact ? 'Exakt' : 'Ortszentrum',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        notes: document.getElementById('notes').value.trim(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              url: document.getElementById('url').value.trim()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const list = getHotels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          list.unshift(entry);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              saveHotels(list);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  status.textContent = `✅ Gespeichert! Flughafen ${airport?.iata ?? '?'}: ${airportMinutes ?? '?'} Min. | Strand: ${beachMeters !== null ? beachMeters + ' m' : '> 4 km'}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      e.target.reset();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          window.history.replaceState({}, document.title, './index.html');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                status.textContent = `❌ Fehler: ${err.message}`;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  } finally {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      btn.disabled = false;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // 6. CSV-Export & Android Share-Sheet (für OneDrive)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById('exportBtn').addEventListener('click', async () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const list = getHotels();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (list.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert('Keine Hotels zum Exportieren vorhanden.');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const headers = [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'Datum',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'Hotel',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'Ort',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'Preis_EUR',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'Verpflegung',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'Bewertung',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'Reisezeitraum',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'Flughafen',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'Fahrtdauer_Flughafen_Min',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'Entfernung_Strand_m',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'Geo_Genauigkeit',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'Notiz',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'Check24_Link'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const escapeCsv = (val) => `"${String(val ?? '').replace(/"/g, '""')}"`;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const rows = list.map((h) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      [
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            h.datum,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  h.hotelName,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        h.location,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              h.price,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    h.board,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          h.rating,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                h.travelDate,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      h.airportIata,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            h.airportMinutes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  h.beachMeters,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        h.exactMatch,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              h.notes,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    h.url
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              .map(escapeCsv)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    .join(';')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const csvContent = '\uFEFF' + [headers.join(';'), ...rows].join('\n');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const file = new File([csvContent], 'check24_hotels.csv', { type: 'text/csv;charset=utf-8;' });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (navigator.canShare && navigator.canShare({ files: [file] })) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                try {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      await navigator.share({
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              title: 'Check24 Hotels CSV',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      files: [file]
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } catch (err) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (err.name === 'AbortError') return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const a = document.createElement('a');
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      a.href = URL.createObjectURL(file);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        a.download = 'check24_hotels.csv';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          a.click();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if (document.readyState === 'loading') {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.addEventListener('DOMContentLoaded', () => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                parseSharedData();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    renderList();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      } else {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        parseSharedData();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          renderList();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }